import rawPool from "@/data/scrambles.json";
import type { Scramble, ScramblePool, SwapMove } from "@/lib/types";

/**
 * The generated pool of 500 scrambles, bundled with the app so it works
 * offline with no fetch. Generated by `npm run scrambles`.
 */
export const scramblePool: ScramblePool = {
  ...rawPool,
  scrambles: rawPool.scrambles.map(
    (s): Scramble => ({ id: s.id, board: s.board, solution: s.solution as SwapMove[] }),
  ),
};

export function findScramble(id: string): Scramble | undefined {
  return scramblePool.scrambles.find((s) => s.id === id);
}
